import { test, expect } from '@playwright/test';

test.describe('Data Refresh After Mutation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-table');
  });

  test('should automatically refresh data after mutation', async ({ page }) => {
    // Verify initial data is displayed
    const tableRows = page.getByRole('row', { name: /item/i });
    await expect(tableRows).toHaveCount(3);

    // Verify initial data count
    const dataCount = page.getByText(/3 items/i);
    await expect(dataCount).toBeVisible();

    // Perform mutation by clicking the edit button on the first row
    const editButton = page.getByRole('button', { name: /edit/i });
    await editButton.click();

    // Wait for mutation API to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/data/mutate') && response.status() === 200
    );

    // Verify mutation success message
    const successMessage = page.getByText(/mutation successful/i);
    await expect(successMessage).toBeVisible();

    // Verify data is refreshed
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for data to reload
    await page.waitForResponse(response => 
      response.url().includes('/api/data/list') && response.status() === 200
    );

    // Verify new data count
    const newDataCount = page.getByText(/4 items/i);
    await expect(newDataCount).toBeVisible();

    // Verify new data is displayed
    const newTableRows = page.getByRole('row', { name: /item/i });
    await expect(newTableRows).toHaveCount(4);

    // Verify mutation details are displayed
    const mutationDetails = page.getByText(/updated item 1/i);
    await expect(mutationDetails).toBeVisible();
  });

  test('should handle failed data refresh after mutation', async ({ page }) => {
    // Verify initial data is displayed
    const tableRows = page.getByRole('row', { name: /item/i });
    await expect(tableRows).toHaveCount(3);

    // Verify initial data count
    const dataCount = page.getByText(/3 items/i);
    await expect(dataCount).toBeVisible();

    // Perform mutation by clicking the edit button on the first row
    const editButton = page.getByRole('button', { name: /edit/i });
    await editButton.click();

    // Simulate failed mutation by intercepting the response
    await page.route('**/api/data/mutate', route => {
      route.abort('Failed to mutate data');
    });

    // Wait for mutation API to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/data/mutate') && response.status() === 200
    );

    // Verify error message
    const errorMessage = page.getByText(/mutation failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify data is not refreshed
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for data to reload
    await page.waitForResponse(response => 
      response.url().includes('/api/data/list') && response.status() === 200
    );

    // Verify data count remains the same
    const dataCount = page.getByText(/3 items/i);
    await expect(dataCount).toBeVisible();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();
  });
});
